-- =====================================================================
-- 0014_es_content.sql
-- BodyMy — Tradução do CONTEÚDO para espanhol (UPDATE IN PLACE).
--
-- GERADO por scripts/gen-es-content-migration.ts a partir das fontes
-- traduzidas em supabase/content/. NÃO edite à mão — regenere.
--
-- Idempotente. Atualiza por POSIÇÃO (preserva ids → sem perda de progresso):
--   * program_weeks.titulo, program_days.titulo, lessons.titulo+conteudo
--     (programa canônico, por semana/dia)
--   * exercises.nome+descricao e a variação v1 (instrucoes), por dia/ordem
--   * stretches.nome+descricao, por ordem
--   * products (drenagem, pilates-hormonal e vitrine) — nome/descrição/sales_page
--   * diet_days.refeicoes (plano base, por numero)
-- =====================================================================

do $migration$
declare
  v_program_id uuid;
  v_ex_id      uuid;
  v_weeks jsonb := $weeks$[{"numero":1,"titulo":"Semana 1 — Reconociendo el cuerpo","dias":[{"numero":1,"titulo":"Lunes","aula":{"titulo":"Llegando al cuerpo","conteudo":{"intro":"¡Bienvenida! Hoy no vamos a \"hacer ejercicio\" — solo vamos a llegar. Acostarte, respirar y percibir el cuerpo que ya está aquí. Es la base de todo lo que viene después.","blocos":[{"tipo":"aviso","titulo":"Antes de empezar","conteudo":"Este contenido es educativo y de bienestar — no sustituye la fisioterapia, al médico ni a otro profesional de la salud. Respeta siempre tus límites: el movimiento es para dar alivio, nunca dolor. Si sientes dolor, mareo o incomodidad, detente y, si es necesario, busca orientación profesional. Si tienes alguna condición de salud, habla con tu médico antes de empezar."},{"tipo":"texto","titulo":"Preparación","conteudo":"Recuéstate boca arriba sobre un tapete, toalla o en la cama. Dobla las rodillas con los pies apoyados, al ancho de la cadera. Deja los brazos a los lados del cuerpo. Si te resulta más cómodo, coloca una almohada fina bajo la cabeza."},{"tipo":"passo","titulo":"Sintiendo el apoyo","conteudo":"Cómo hacerlo: Cierra los ojos y percibe los puntos del cuerpo que tocan el suelo: la cabeza, la espalda, la cadera, los pies. No cambies nada, solo observa.\nRespiración: Respira por la nariz, a tu ritmo natural, sin controlar.\nRepeticiones: 1 minuto observando.\nVas a sentir: el peso del cuerpo entregándose al apoyo, como si te hundieras un poquito.\n⚠️ Señal para detenerte: nada aquí exige fuerza — si la zona lumbar molesta, acerca más los pies a la cadera."},{"tipo":"passo","titulo":"Respiración en la panza","conteudo":"Cómo hacerlo: Lleva una mano a la panza. Al inspirar, deja que la panza suba suavemente bajo la mano; al soltar el aire, deja que baje. Sin empujar.\nRespiración: Inspira contando hasta 3, suelta contando hasta 4.\nRepeticiones: 8 a 10 respiraciones lentas.\nVas a sentir: la panza moviéndose con el aire, y los hombros poniéndose más pesados.\n⚠️ Señal para detenerte: si te mareas o te falta el aire, vuelve a la respiración normal."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Quédate un instante más acostada, sintiendo cómo está el cuerpo ahora. Después abre los ojos despacio. Listo — ya empezaste."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"No necesitas \"hacerlo bonito\". En lo somático, aparecer y sentir ya es la práctica entera. El resto llega solo."}]}}},{"numero":2,"titulo":"Martes","aula":{"titulo":"La respiración que suelta","conteudo":{"intro":"Hoy unimos la respiración con un micromovimiento de los hombros. Cuando la respiración guía, el cuerpo se suelta sin esfuerzo.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Acostada boca arriba, rodillas dobladas y pies apoyados. Brazos a los lados del cuerpo, palmas hacia arriba."},{"tipo":"passo","titulo":"Hombros que suben y se derriten","conteudo":"Cómo hacerlo: Al inspirar, lleva suavemente los hombros hacia las orejas (muy poco). Al exhalar, deja que se \"derritan\" de vuelta, alejándose de las orejas.\nRespiración: Inspira subiendo los hombros, suelta el aire bajándolos.\nRepeticiones: 6 veces, sin apuro.\nVas a sentir: la diferencia entre el hombro tenso (subiendo) y el hombro suelto (bajando).\n⚠️ Señal para detenerte: hazlo pequeño — si el cuello se queja, reduce el movimiento."},{"tipo":"passo","titulo":"Abrir el pecho con el aire","conteudo":"Cómo hacerlo: Al inspirar, deja que el pecho se abra levemente; al soltar, deja que las costillas se cierren como un abanico. El movimiento es interno, casi invisible.\nRespiración: Respiración lenta, guiando la apertura y el cierre.\nRepeticiones: 8 respiraciones.\nVas a sentir: el pecho ganando espacio, y la respiración volviéndose más fácil.\n⚠️ Señal para detenerte: nada de arquear la zona lumbar; el movimiento es solo de las costillas."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Descansa los brazos y siente los hombros. Compara con el comienzo: suelen estar más bajos y ligeros."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Fíjate cuántas veces al día contienes el aire sin darte cuenta — en un mensaje difícil, en el tráfico. Soltar el aire ya es soltar tensión."}]}}},{"numero":3,"titulo":"Miércoles","aula":{"titulo":"Balanceo de la pelvis","conteudo":{"intro":"Un movimiento pequeño y delicioso para la zona lumbar: inclinar la cadera hacia adelante y hacia atrás, despacio, dejando que la columna acompañe.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Acostada boca arriba, rodillas dobladas, pies apoyados al ancho de la cadera. Manos descansando en la panza o a los lados del cuerpo."},{"tipo":"passo","titulo":"Báscula de la pelvis","conteudo":"Cómo hacerlo: Imagina la cadera como un tazón con agua. Inclínala levemente hacia atrás (la zona lumbar se acerca al suelo) y después hacia adelante (la zona lumbar hace un pequeño arco). Movimiento diminuto y lento.\nRespiración: Suelta el aire al acercar la zona lumbar al suelo; inspira al volver.\nRepeticiones: 8 a 10 balanceos suaves.\nVas a sentir: la zona lumbar \"rodando\" entre los dos puntos, sin esfuerzo de las piernas.\n⚠️ Señal para detenerte: si aparece cualquier punzada, reduce la amplitud a la mitad."},{"tipo":"passo","titulo":"Pausa y sentir","conteudo":"Cómo hacerlo: Detente a la mitad, en la posición más neutra y cómoda. Solo observa la zona lumbar apoyada.\nRespiración: Tres respiraciones lentas.\nRepeticiones: 30 segundos.\nVas a sentir: la región que antes estaba tensa un poco más suave.\n⚠️ Señal para detenerte: ninguna — esta es solo la pausa."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Estira las piernas despacio, una a la vez, y siente la zona lumbar. Menos rígida suele ser la sensación."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"A la zona lumbar no le gusta quedarse quieta todo el día. Este balanceo cabe hasta en la cama, antes de dormir."}]}}},{"numero":4,"titulo":"Jueves","aula":{"titulo":"Pausa consciente (práctica ligera)","conteudo":{"intro":"Día más tranquilo. Nada de \"hacer\" — hoy es reconocer el cuerpo entero con atención. La práctica ligera también es constancia, y mantiene viva tu racha.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Recuéstate cómoda, boca arriba, piernas estiradas o rodillas dobladas — lo que te resulte mejor. Una cobija si quieres abrigo."},{"tipo":"passo","titulo":"Barrido del cuerpo","conteudo":"Cómo hacerlo: Lleva la atención a los pies y sube lentamente: piernas, cadera, panza, pecho, manos, hombros, cuello, rostro. En cada región, solo percibe cómo está — sin cambiar nada.\nRespiración: Respiración natural, tranquila.\nRepeticiones: Un recorrido completo, unos 5 minutos.\nVas a sentir: qué regiones están sueltas y cuáles piden más atención.\n⚠️ Señal para detenerte: si la mente se dispersa, está bien — vuelve con suavidad a donde te quedaste."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Quédate acostada un minuto más, sin hacer nada. Después vuelve despacio."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Descansar con atención es distinto de desconectarte frente a la tele: aquí el cuerpo aprende a soltar. Eso también es entrenamiento."}]}}},{"numero":5,"titulo":"Viernes","aula":{"titulo":"La cabeza que gira","conteudo":{"intro":"Vamos a sentarnos y soltar el cuello con un movimiento lento de girar la cabeza. Aquí vive mucha de la tensión del día.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Siéntate en una silla firme, pies apoyados en el suelo, columna larga y relajada. Manos sobre los muslos."},{"tipo":"passo","titulo":"Girar la mirada","conteudo":"Cómo hacerlo: Gira la cabeza lentamente hacia la derecha, como si fueras a mirar por encima del hombro, solo hasta donde sea cómodo. Vuelve al centro. Después hacia la izquierda.\nRespiración: Suelta el aire al girar, inspira al volver al centro.\nRepeticiones: 4 veces hacia cada lado.\nVas a sentir: el cuello deslizándose, sin \"trabarse\" al final del movimiento.\n⚠️ Señal para detenerte: no fuerces para ver más atrás; detente donde todavía se sienta agradable."},{"tipo":"passo","titulo":"Oreja al hombro","conteudo":"Cómo hacerlo: Inclina la cabeza llevando la oreja derecha hacia el hombro derecho (sin subir el hombro). Vuelve al centro y cambia de lado.\nRespiración: Exhala al inclinar, inspira al volver.\nRepeticiones: 3 veces hacia cada lado.\nVas a sentir: un estiramiento suave en el costado del cuello.\n⚠️ Señal para detenerte: si baja un hormigueo por el brazo, vuelve de inmediato al centro."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Vuelve la mirada al centro, cierra los ojos y siente el cuello. Suele quedar más ligero y móvil."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Con el celular, la cabeza se inclina hacia adelante y el cuello paga la cuenta. Este movimiento es un buen \"reinicio\" a mitad del día."}]}}},{"numero":6,"titulo":"Sábado","aula":{"titulo":"Abrir y cerrar","conteudo":{"intro":"Hoy abrimos y cerramos los brazos como un abanico, sentada, dejando que la respiración guíe. Ayuda a soltar la parte alta de la espalda.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Sentada al borde de la silla, pies bien apoyados, columna larga. Brazos al frente, a la altura del pecho, palmas mirándose entre sí."},{"tipo":"passo","titulo":"Abanico de brazos","conteudo":"Cómo hacerlo: Al inspirar, abre los brazos hacia los lados, como si abrieras una ventana; siente el pecho abrirse. Al soltar, trae los brazos de vuelta al frente, redondeando levemente la espalda.\nRespiración: Inspira abriendo, exhala cerrando.\nRepeticiones: 6 veces lentas.\nVas a sentir: el pecho abriéndose en la inspiración y la espalda soltándose en el cierre.\n⚠️ Señal para detenerte: mantén los hombros lejos de las orejas; si suben, hazlo más pequeño."},{"tipo":"passo","titulo":"Autoabrazo","conteudo":"Cómo hacerlo: En la última vez, al cerrar, cruza los brazos en un abrazo a ti misma, una mano en cada hombro. Quédate ahí respirando.\nRespiración: Tres respiraciones lentas dentro del abrazo.\nRepeticiones: 30 segundos.\nVas a sentir: la espalda entre los omóplatos abriéndose con el aire.\n⚠️ Señal para detenerte: ninguna — es contención."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Suelta los brazos sobre el regazo. Percibe la parte alta de la espalda más amplia."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Pasar el día con los hombros \"cerrados\" frente al teclado acorta el pecho. Abrirlos de vez en cuando reequilibra."}]}}},{"numero":7,"titulo":"Domingo","aula":{"titulo":"El cuerpo en reposo (práctica ligera)","conteudo":{"intro":"Cerramos la semana con un movimiento delicioso para la columna, sentada, al ritmo de la respiración. Suave, restaurador — y cuenta como día activo.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Sentada en la silla, pies apoyados, manos sobre los muslos."},{"tipo":"passo","titulo":"Gato y vaca sentada","conteudo":"Cómo hacerlo: Al inspirar, crece por la columna y abre levemente el pecho hacia arriba (vaca). Al soltar, redondea la espalda, mentón hacia el pecho (gato). Muy lento.\nRespiración: Inspira abriendo, exhala redondeando.\nRepeticiones: 8 ciclos.\nVas a sentir: la columna moviéndose vértebra por vértebra, como una ola.\n⚠️ Señal para detenerte: amplitud cómoda; nada de forzar el cuello al final."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Vuelve al centro, columna larga. Siente la semana: apareciste 7 días. Eso es grande."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Si hoy solo tuviste tiempo para 5 minutos, igual valió. Constancia es aparecer, no durar mucho."}]}}}]},{"numero":2,"titulo":"Semana 2 — Soltando tensión","dias":[{"numero":1,"titulo":"Lunes","aula":{"titulo":"Soltando los hombros","conteudo":{"intro":"Vamos a usar la pandiculación — ese estiramiento natural, como cuando te desperezas — para soltar los hombros de verdad: contraer un poco, sostener y soltar bien despacio.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Sentada o de pie, columna larga, brazos sueltos a los lados del cuerpo."},{"tipo":"passo","titulo":"Desperezo de hombros","conteudo":"Cómo hacerlo: Sube los dos hombros hacia las orejas contrayendo suavemente. Sostén 3 segundos sintiendo la leve tensión. Ahora suelta MUY despacio, dejando que los hombros bajen más allá de donde empezaron.\nRespiración: Inspira subiendo, retén el aire en lo alto, suelta el aire bajando lentamente.\nRepeticiones: 4 veces.\nVas a sentir: la \"bajada\" más larga y suelta que la subida — ese es el secreto.\n⚠️ Señal para detenerte: si el cuello se queja, contrae menos."},{"tipo":"passo","titulo":"Círculos de hombro","conteudo":"Cómo hacerlo: Dibuja círculos lentos con los hombros hacia atrás: sube, va hacia atrás, baja, vuelve. Grandes y sin apuro.\nRespiración: Respiración libre, continua.\nRepeticiones: 5 círculos hacia atrás.\nVas a sentir: la articulación del hombro \"lubricándose\", cada vuelta más fácil.\n⚠️ Señal para detenerte: reduce el tamaño del círculo si hay chasquidos con molestia."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Suelta todo y siente los hombros colgando. Ese peso que cargabas sin darte cuenta suele disminuir."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"La pandiculación es lo que hace el gato al despertar. Al cuerpo humano le encanta — nosotros somos los que nos olvidamos de hacerla."}]}}},{"numero":2,"titulo":"Martes","aula":{"titulo":"Cuello libre","conteudo":{"intro":"Hoy es día de darle espacio al cuello con inclinaciones y una rotación bien lenta. Delicadeza es la palabra clave.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Sentada, columna larga, hombros sueltos. Deja una mano descansando sobre el muslo."},{"tipo":"passo","titulo":"Sí y no lentos","conteudo":"Cómo hacerlo: Haz un \"sí\" diminuto con la cabeza (el mentón baja y sube muy poquito) unas cuantas veces; después un \"no\" lento, girando la mirada de un lado a otro.\nRespiración: Respiración tranquila, sin retenerla.\nRepeticiones: 4 \"síes\" y 4 \"noes\", bien pequeños.\nVas a sentir: la base del cráneo deslizándose sobre el cuello.\n⚠️ Señal para detenerte: movimientos pequeños: aquí menos es más."},{"tipo":"passo","titulo":"Media luna del mentón","conteudo":"Cómo hacerlo: Lleva el mentón al pecho (sin forzar) y dibuja una media luna llevando el mentón de un hombro al otro, pasando por el frente. Nunca eches la cabeza hacia atrás.\nRespiración: Suelta el aire mientras dibujas la media luna.\nRepeticiones: 3 veces en cada dirección.\nVas a sentir: la nuca abriéndose y el frente del cuello deslizándose.\n⚠️ Señal para detenerte: sin llevar la cabeza hacia atrás; si te mareas, detente."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Vuelve al centro y cierra los ojos. Siente el cuello con más espacio para respirar."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"La tensión en el cuello muchas veces es la mandíbula apretada. Suelta los dientes: deja un pequeño espacio entre ellos."}]}}},{"numero":3,"titulo":"Miércoles","aula":{"titulo":"Gato y vaca en el suelo","conteudo":{"intro":"El clásico de la movilidad de columna, ahora en cuatro apoyos. Una ola que recorre toda la espalda.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Ponte en cuatro apoyos, manos bajo los hombros y rodillas bajo la cadera, sobre el tapete. Usa una toalla doblada bajo las rodillas si molesta."},{"tipo":"passo","titulo":"La ola de la columna","conteudo":"Cómo hacerlo: Al inspirar, deja que la panza baje y el pecho y la mirada suban levemente (vaca). Al soltar, empuja el suelo y redondea la espalda hacia el techo, mentón al pecho (gato).\nRespiración: Inspira en la vaca, exhala en el gato.\nRepeticiones: 8 a 10 ciclos lentos.\nVas a sentir: cada vértebra participando, del cóccix a la nuca.\n⚠️ Señal para detenerte: si las muñecas molestan, apóyate en los antebrazos o reduce el tiempo."},{"tipo":"passo","titulo":"Postura del niño","conteudo":"Cómo hacerlo: Lleva la cadera hacia los talones y recuesta el tronco hacia adelante, brazos estirados o a los lados del cuerpo. Frente apoyada.\nRespiración: Respira hacia la espalda, sintiéndola subir.\nRepeticiones: 5 respiraciones.\nVas a sentir: la espalda abriéndose con cada inspiración.\n⚠️ Señal para detenerte: si las rodillas se quejan, sepáralas o coloca una almohada detrás de ellas."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Vuelve despacio a sentarte sobre los talones o de lado. Siente la columna más fluida."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"La columna tiene unas 30 piezas a las que les encanta moverse juntas. Está hecha para ondular, no para quedarse recta todo el día."}]}}},{"numero":4,"titulo":"Jueves","aula":{"titulo":"Respirar y soltar (práctica ligera)","conteudo":{"intro":"Día restaurativo con las piernas apoyadas para descansar la zona lumbar y las piernas cansadas. Poco movimiento, mucho alivio.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Recuéstate boca arriba cerca de una pared o de una silla. Coloca las pantorrillas sobre el asiento de la silla (rodillas dobladas a 90°) o las piernas apoyadas en la pared, lo que te resulte cómodo."},{"tipo":"passo","titulo":"Piernas en reposo","conteudo":"Cómo hacerlo: Con las piernas apoyadas, deja que la zona lumbar se relaje en el suelo. No hagas nada con las piernas — solo descansa su peso sobre el apoyo.\nRespiración: Respiración larga y lenta, con la exhalación más prolongada que la inspiración.\nRepeticiones: 3 a 4 minutos.\nVas a sentir: la zona lumbar y las piernas \"apagándose\", poniéndose pesadas.\n⚠️ Señal para detenerte: si hormiguea demasiado, retira las piernas del apoyo y estíralas en el suelo."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Rueda hacia un lado, quédate un instante, y levántate sin apuro. Piernas más ligeras es la sensación común."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"¿Pasaste el día de pie o sentada? Cinco minutos con las piernas apoyadas hacen más por tu energía de lo que parece."}]}}},{"numero":5,"titulo":"Viernes","aula":{"titulo":"La cadera que se abre","conteudo":{"intro":"La cadera guarda mucha tensión de quien pasa horas sentada. Vamos a soltarla con movimientos lentos, acostada.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Acostada boca arriba, rodillas dobladas, pies apoyados al ancho de la cadera."},{"tipo":"passo","titulo":"Rodillas que se balancean","conteudo":"Cómo hacerlo: Con los pies un poco más separados, deja que las dos rodillas caigan suavemente hacia la derecha y después hacia la izquierda, como limpiaparabrisas lentos.\nRespiración: Suelta el aire al llevar las rodillas hacia el lado, inspira al volver al centro.\nRepeticiones: 6 veces hacia cada lado.\nVas a sentir: la cadera y la zona lumbar girando con ligereza.\n⚠️ Señal para detenerte: amplitud pequeña; no fuerces las rodillas hacia el suelo."},{"tipo":"passo","titulo":"Abrir una rodilla","conteudo":"Cómo hacerlo: Mantén un pie apoyado y deja que la otra rodilla se abra hacia el lado (como un libro abriéndose), solo hasta donde sea cómodo. Vuelve y cambia de pierna.\nRespiración: Exhala al abrir, inspira al cerrar.\nRepeticiones: 4 veces con cada pierna.\nVas a sentir: la ingle y la parte interna del muslo abriéndose suavemente.\n⚠️ Señal para detenerte: si sientes un tirón incómodo en la ingle, abre menos."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Abraza las rodillas contra el pecho por unos segundos, si te resulta cómodo, y después estira las piernas. Cadera más libre."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Una cadera rígida suele sobrecargar la zona lumbar. Soltar la cadera es un regalo indirecto para tu espalda."}]}}},{"numero":6,"titulo":"Sábado","aula":{"titulo":"La zona lumbar que descansa","conteudo":{"intro":"Enfoque cariñoso en la zona lumbar hoy: un balanceo de pelvis más amplio y un abrazo de rodillas que suele dar alivio inmediato.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Acostada boca arriba, rodillas dobladas, pies apoyados. Brazos a los lados del cuerpo."},{"tipo":"passo","titulo":"Balanceo amplio de la pelvis","conteudo":"Cómo hacerlo: Retoma el balanceo de pelvis del Día 3, ahora dejando que la ola suba un poco más por la columna: al acercar la zona lumbar al suelo, deja que el cóccix suba levemente.\nRespiración: Suelta el aire al apoyar la zona lumbar, inspira al soltar.\nRepeticiones: 8 balanceos.\nVas a sentir: la zona lumbar masajeando el suelo suavemente.\n⚠️ Señal para detenerte: sin levantar la cadera muy alto; la ola es pequeña."},{"tipo":"passo","titulo":"Abrazo de rodillas","conteudo":"Cómo hacerlo: Trae una rodilla a la vez hacia el pecho y sostenla por detrás del muslo (no sobre la rodilla). Deja que la zona lumbar se hunda en el suelo.\nRespiración: Respira hacia la espalda, con una exhalación larga.\nRepeticiones: 5 respiraciones; suelta y repite 1 vez.\nVas a sentir: la zona lumbar abriéndose y descansando en el apoyo.\n⚠️ Señal para detenerte: si es demasiado para las dos rodillas, hazlo una a la vez."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Devuelve los pies al suelo, estira las piernas despacio y siente la zona lumbar más tranquila."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"El dolor lumbar leve muchas veces mejora con movimiento suave, no con reposo total. Pero un dolor fuerte o que baja por la pierna pide evaluación profesional."}]}}},{"numero":7,"titulo":"Domingo","aula":{"titulo":"Torsión suave (práctica ligera)","conteudo":{"intro":"Cerramos la semana con una torsión restauradora acostada — de esas que la columna agradece. Movimiento mínimo, alivio grande.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Acostada boca arriba, rodillas dobladas y pies apoyados. Brazos abiertos en cruz, palmas hacia arriba."},{"tipo":"passo","titulo":"Torsión con las rodillas","conteudo":"Cómo hacerlo: Junta las rodillas y déjalas caer despacio hacia un lado, mientras la mirada va hacia el lado opuesto, si te resulta cómodo. Vuelve al centro y cambia.\nRespiración: Suelta el aire al girar, inspira al volver.\nRepeticiones: 3 a 4 veces hacia cada lado, con una pausa de una respiración al final.\nVas a sentir: una torsión suave a lo largo de la columna y el pecho abriéndose.\n⚠️ Señal para detenerte: los hombros permanecen apoyados; si uno se levanta demasiado, gira menos."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Vuelve al centro, abraza las rodillas por un instante y estira las piernas. Dos semanas completadas — tu cuerpo ya reconoce la práctica."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"¿Notaste que ya entiendes mejor las señales del cuerpo que en el Día 1? Esa escucha es el verdadero resultado."}]}}}]},{"numero":3,"titulo":"Semana 3 — Movimiento integrado","dias":[{"numero":1,"titulo":"Lunes","aula":{"titulo":"Del suelo a de pie","conteudo":{"intro":"Esta semana el cuerpo se integra. Empezamos aprendiendo a levantarnos del suelo con conciencia — un movimiento cotidiano que merece ser suave.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Empieza acostada boca arriba, rodillas dobladas. Ten espacio libre alrededor."},{"tipo":"passo","titulo":"Rodar hacia el lado","conteudo":"Cómo hacerlo: Gira la cabeza hacia un lado y deja que todo el cuerpo ruede hacia ese lado, como un tronco. Llega de lado, con las rodillas dobladas.\nRespiración: Suelta el aire al rodar.\nRepeticiones: 2 veces hacia cada lado.\nVas a sentir: el cuerpo moviéndose en bloque, sin \"jalarse\" por el cuello.\n⚠️ Señal para detenerte: usa las manos para ayudarte; nada de esfuerzo en el cuello."},{"tipo":"passo","titulo":"Subir a sentada y a de pie","conteudo":"Cómo hacerlo: De lado, apoya las manos en el suelo y empuja para sentarte. Después lleva un pie hacia adelante y usa las manos sobre los muslos para subir despacio hasta quedar de pie.\nRespiración: Exhala en los momentos de esfuerzo (empujar, subir).\nRepeticiones: 3 subidas conscientes.\nVas a sentir: las piernas trabajando, el movimiento organizado desde el suelo hasta de pie.\n⚠️ Señal para detenerte: apóyate en una silla firme si lo necesitas; sin apuro."},{"tipo":"texto","titulo":"Para terminar","conteudo":"De pie, siente los pies en el suelo y la columna larga. Acabas de transformar un gesto automático en práctica."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"La forma en que te levantas del suelo o de la cama dice mucho. Hacerlo despacio le ahorra esfuerzo a tu zona lumbar todos los días."}]}}},{"numero":2,"titulo":"Martes","aula":{"titulo":"La columna que se desenrolla","conteudo":{"intro":"El roll down: bajar la columna vértebra por vértebra y volver a subir. Uno de los movimientos más ricos para soltar la espalda de pie.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"De pie, pies al ancho de la cadera, rodillas suuuaves (nunca trabadas). Brazos sueltos."},{"tipo":"passo","titulo":"Desenrollar hacia abajo","conteudo":"Cómo hacerlo: Deja que el mentón caiga hacia el pecho y ve bajando la columna poco a poco, como si te desenrollaras hueso por hueso, el tronco cayendo hacia adelante. Baja solo hasta donde sea cómodo, rodillas suaves.\nRespiración: Suelta el aire durante todo el descenso.\nRepeticiones: 4 veces.\nVas a sentir: la espalda abriéndose y la cabeza pesada colgando.\n⚠️ Señal para detenerte: no fuerces las manos hacia el suelo; la amplitud es tuya. ¿Mareo al volver? Sube más despacio."},{"tipo":"passo","titulo":"Enrollar hacia arriba","conteudo":"Cómo hacerlo: Para volver, empieza por la base de la columna, apilando vértebra por vértebra, y deja que la cabeza sea la última en subir.\nRespiración: Inspira subiendo, lentamente.\nRepeticiones: con cada roll down, continúa directo hacia el roll up.\nVas a sentir: la columna \"apilándose\" y el cuerpo volviéndose alto otra vez.\n⚠️ Señal para detenerte: si te mareas, pausa a medio camino y respira."},{"tipo":"texto","titulo":"Para terminar","conteudo":"De pie, ojos cerrados, siente la columna larga y la espalda suelta. Percibe la respiración más tranquila."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Las rodillas \"blanditas\" aquí no son flojera — son protección. Trabar las rodillas manda toda la carga a la zona lumbar."}]}}},{"numero":3,"titulo":"Miércoles","aula":{"titulo":"Brazos que respiran","conteudo":{"intro":"Un flujo suave de brazos de pie, guiado por la respiración. Abre el pecho, suelta los hombros y calma la mente.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"De pie, pies al ancho de la cadera, rodillas suaves, brazos a los lados del cuerpo."},{"tipo":"passo","titulo":"Brazos que suben con el aire","conteudo":"Cómo hacerlo: Al inspirar, sube los brazos por los lados hasta arriba de la cabeza (o hasta donde sea cómodo). Al soltar, bájalos por el frente, despacio.\nRespiración: Inspira subiendo, exhala bajando.\nRepeticiones: 6 veces.\nVas a sentir: el aire \"levantando\" los brazos y el pecho abriéndose en lo alto.\n⚠️ Señal para detenerte: si los hombros suben demasiado o el cuello se tensa, sube menos."},{"tipo":"passo","titulo":"Recoger agua","conteudo":"Cómo hacerlo: Inclina levemente el tronco hacia adelante (rodillas suaves) y haz el gesto de \"recoger agua\" con las manos, trayéndolas hacia el pecho al subir el tronco, como si te ofrecieras algo a ti misma.\nRespiración: Inspira al recoger, exhala al soltar las manos hacia abajo.\nRepeticiones: 5 veces, en un flujo continuo.\nVas a sentir: el movimiento entero conectado — piernas, tronco, brazos, respiración.\n⚠️ Señal para detenerte: mantén las rodillas suaves y la zona lumbar larga."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Detente de pie, brazos a los lados del cuerpo, y siente el efecto: pecho abierto, hombros bajos, respiración amplia."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Cuando la respiración guía el movimiento, el ejercicio se vuelve casi una meditación de pie. Fíjate cómo la mente se vacía."}]}}},{"numero":4,"titulo":"Jueves","aula":{"titulo":"Equilibrio calmo (práctica ligera)","conteudo":{"intro":"Día más tranquilo para jugar con el peso del cuerpo y el equilibrio — sin desafío, solo percepción. Suave, y cuenta como constancia.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"De pie, cerca de una pared o silla para apoyo, pies al ancho de la cadera."},{"tipo":"passo","titulo":"Transferir el peso","conteudo":"Cómo hacerlo: Pasa el peso lentamente al pie derecho, sintiéndolo hundirse en el suelo; después al izquierdo. Como un péndulo lento.\nRespiración: Respiración natural y continua.\nRepeticiones: 8 transferencias.\nVas a sentir: los pies \"leyendo\" el suelo y el cuerpo organizándose solo.\n⚠️ Señal para detenerte: mantén la mano cerca del apoyo; sujétate si lo necesitas."},{"tipo":"passo","titulo":"En puntas, despacio","conteudo":"Cómo hacerlo: Sube levemente en las puntas de los pies y baja bien despacio, controlando el descenso. Usa el apoyo con toda confianza.\nRespiración: Inspira subiendo, exhala bajando lentamente.\nRepeticiones: 5 veces.\nVas a sentir: las pantorrillas trabajando y los tobillos ganando firmeza.\n⚠️ Señal para detenerte: si el equilibrio se tambalea, mantén la mano en el apoyo todo el tiempo."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Quédate un instante con los pies completos en el suelo, sintiéndote firme y presente."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"El equilibrio no es un don, es práctica. Cada vez que lo entrenas con calma, el cuerpo se vuelve más seguro en el día a día."}]}}},{"numero":5,"titulo":"Viernes","aula":{"titulo":"Cadera de pie","conteudo":{"intro":"Llevamos la soltura de la cadera a la posición de pie, con círculos lentos y una sentadilla suave y apoyada.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"De pie, pies un poco más separados que la cadera, rodillas suaves. Manos en la cintura o cerca de un apoyo."},{"tipo":"passo","titulo":"Círculos de cadera","conteudo":"Cómo hacerlo: Dibuja círculos lentos con la cadera, como si movieras un hula-hula imaginario despacio. Hazlo en un sentido y después en el otro.\nRespiración: Respiración libre y continua.\nRepeticiones: 5 círculos hacia cada lado.\nVas a sentir: la cadera soltándose y la zona lumbar acompañando con ligereza.\n⚠️ Señal para detenerte: círculos pequeños; nada de forzar la zona lumbar."},{"tipo":"passo","titulo":"Sentadilla apoyada","conteudo":"Cómo hacerlo: De frente a una silla o mesada, sostente levemente como apoyo. Dobla las rodillas y lleva la cadera hacia atrás y hacia abajo, solo hasta la mitad del camino, y vuelve.\nRespiración: Inspira al bajar, exhala al subir.\nRepeticiones: 6 veces suaves.\nVas a sentir: los muslos y la cadera trabajando, las rodillas alineadas con los pies.\n⚠️ Señal para detenerte: baja solo hasta donde sea cómodo; la rodilla nunca debe doler."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Quédate de pie, suelta los brazos y siente la base del cuerpo más despierta y firme."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Sentarte y levantarte de la silla todo el día ya es una sentadilla. Hacerlo con conciencia algunas veces mejora el gesto entero."}]}}},{"numero":6,"titulo":"Sábado","aula":{"titulo":"Columna en espiral","conteudo":{"intro":"Rotaciones suaves de pie que integran columna, hombros y cadera. La espiral es un movimiento muy natural y liberador.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"De pie, pies al ancho de la cadera, rodillas suaves, brazos sueltos."},{"tipo":"passo","titulo":"Girar como un trompo lento","conteudo":"Cómo hacerlo: Deja los brazos sueltos y gira el tronco suavemente de un lado a otro, permitiendo que los brazos \"golpeen\" levemente el cuerpo. Los talones pueden despegarse un poco del suelo.\nRespiración: Respiración libre, suelta.\nRepeticiones: 10 giros suaves, alternando los lados.\nVas a sentir: la columna torciéndose con ligereza y los hombros balanceándose sueltos.\n⚠️ Señal para detenerte: sin forzar la torsión al final; deja que la inercia te lleve."},{"tipo":"passo","titulo":"Espiral consciente","conteudo":"Cómo hacerlo: Ahora más despacio: al inspirar vuelve al centro; al soltar, gira hacia un lado llevando la mirada por encima del hombro. Alterna.\nRespiración: Exhala girando, inspira al centro.\nRepeticiones: 4 hacia cada lado.\nVas a sentir: la diferencia entre la torsión suelta (antes) y la torsión consciente (ahora).\n⚠️ Señal para detenerte: detente si sientes mareo; retoma cuando pase."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Vuelve al centro, respira profundo y siente la columna más móvil desde las caderas hasta los hombros."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"La columna gira mejor cuando el cuello no \"jala\" el movimiento. Deja que la mirada acompañe, no que lidere."}]}}},{"numero":7,"titulo":"Domingo","aula":{"titulo":"Fluir despacio (práctica ligera)","conteudo":{"intro":"Una minisecuencia restaurativa que junta lo que trajo la semana: desenrollar, brazos y respiración. Ligera, fluida, deliciosa.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"De pie, con espacio, rodillas suaves."},{"tipo":"passo","titulo":"Secuencia de cierre de semana","conteudo":"Cómo hacerlo: Encadena despacio: los brazos suben con la inspiración → desenrolla la columna hacia abajo soltando el aire → pausa colgada por una respiración → enrolla de vuelta hacia arriba → los brazos bajan por el frente.\nRespiración: Deja que la respiración marque el ritmo de cada parte.\nRepeticiones: 4 rondas lentas, cada una más fluida.\nVas a sentir: las partes conectándose en un único movimiento continuo.\n⚠️ Señal para detenerte: sin apuro entre las fases; si te mareas al subir, sube más despacio."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Quédate de pie, ojos cerrados, y siente el cuerpo entero reunido y calmo. Tres semanas — estás más presente en tu propio cuerpo."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Una secuencia solo tuya ya está naciendo. La próxima semana vas a armar la que más combine con tus días."}]}}}]},{"numero":4,"titulo":"Semana 4 — Práctica consolidada","dias":[{"numero":1,"titulo":"Lunes","aula":{"titulo":"Tu secuencia de la mañana","conteudo":{"intro":"Una secuencia completa para empezar el día despertando el cuerpo con delicadeza. Guarda esta — puede convertirse en tu rutina matutina.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Empieza acostada en la cama o en el tapete, al despertar. Después pasamos a sentada y de pie. Ten un apoyo cerca."},{"tipo":"passo","titulo":"Despertar acostada","conteudo":"Cómo hacerlo: Despereza el cuerpo entero (pandiculación): estira brazos y piernas en direcciones opuestas, sostén y suelta. Después haz 6 balanceos de pelvis.\nRespiración: Inspira al estirarte, suelta al relajarte.\nRepeticiones: 2 desperezos + 6 balanceos.\nVas a sentir: el cuerpo saliendo del modo \"dormido\" con gusto.\n⚠️ Señal para detenerte: movimientos generosos, pero sin calambres; si aparece uno, relaja."},{"tipo":"passo","titulo":"Sentarse y abrir","conteudo":"Cómo hacerlo: Rueda hacia un lado, siéntate. Haz 6 \"abanicos\" de brazos (Día 6) abriendo el pecho y 4 rotaciones de cabeza (Día 5).\nRespiración: La respiración guiando cada apertura.\nRepeticiones: como se describió.\nVas a sentir: el tronco y el cuello soltándose de la rigidez matutina.\n⚠️ Señal para detenerte: despacio — por la mañana el cuerpo está más \"corto\"."},{"tipo":"passo","titulo":"Levantarse y crecer","conteudo":"Cómo hacerlo: Sube a ponerte de pie con conciencia (Día 15). Haz 4 subidas de brazos con la respiración y termina con un roll down suave.\nRespiración: Inspira subiendo los brazos, exhala desenrollando.\nRepeticiones: como se describió.\nVas a sentir: el cuerpo despierto, abierto y listo para el día.\n⚠️ Señal para detenerte: rodillas suaves en el roll down; sube sin apuro."},{"tipo":"texto","titulo":"Para terminar","conteudo":"De pie, tres respiraciones largas. Fíjate qué diferente es empezar el día así."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Hacer esto antes de agarrar el celular cambia el tono del día entero. Pruébalo por algunos días y siéntelo."}]}}},{"numero":2,"titulo":"Martes","aula":{"titulo":"Soltar el día","conteudo":{"intro":"Secuencia para el final del día: descargar la tensión acumulada en el cuello, los hombros y la zona lumbar antes de descansar.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Empieza sentada en una silla; después vamos al suelo. Una luz tenue ayuda a bajar el ritmo."},{"tipo":"passo","titulo":"Descargar desde arriba","conteudo":"Cómo hacerlo: Sentada: 4 desperezos de hombros (Día 8), la media luna del mentón (Día 9) y el autoabrazo (Día 6).\nRespiración: Exhalaciones largas en cada soltura.\nRepeticiones: como se describió.\nVas a sentir: el peso del día saliendo de los hombros y del cuello.\n⚠️ Señal para detenerte: nada de forzar; hoy es para soltar, no para conquistar."},{"tipo":"passo","titulo":"Soltar la zona lumbar","conteudo":"Cómo hacerlo: En el suelo: gato y vaca (Día 10), abrazo de rodillas (Día 13) y torsión suave (Día 14).\nRespiración: Respiración hacia la espalda.\nRepeticiones: como se describió.\nVas a sentir: la zona lumbar y la cadera abriéndose y descansando.\n⚠️ Señal para detenerte: si algo molesta, sáltate ese movimiento y sigue."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Termina acostada, piernas estiradas, por un minuto. Cuerpo más ligero para dormir."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Llevar tensión a la cama afecta el sueño. Cinco minutos de soltura en la noche valen por horas de dar vueltas en la cama."}]}}},{"numero":3,"titulo":"Miércoles","aula":{"titulo":"Cuerpo entero","conteudo":{"intro":"La secuencia más completa del protocolo, integrando las cuatro semanas. Resérvate un poco más de tiempo y disfruta cada parte.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Espacio libre, tapete, y un apoyo cerca. Empieza de pie."},{"tipo":"passo","titulo":"Calentar y desenrollar","conteudo":"Cómo hacerlo: De pie: brazos que respiran (Día 17), espiral consciente (Día 20) y roll down/roll up (Día 16).\nRespiración: La respiración marcando cada fase.\nRepeticiones: 2 rondas de cada.\nVas a sentir: el cuerpo entrando en calor y la columna ganando fluidez.\n⚠️ Señal para detenerte: rodillas suaves; sube despacio de los roll downs."},{"tipo":"passo","titulo":"Base firme","conteudo":"Cómo hacerlo: Círculos de cadera (Día 19) y sentadilla apoyada (Día 19), después transferencia de peso (Día 18).\nRespiración: Inspira bajando, exhala subiendo.\nRepeticiones: como se describió.\nVas a sentir: la base del cuerpo despierta y firme.\n⚠️ Señal para detenerte: amplitud cómoda en las rodillas."},{"tipo":"passo","titulo":"Volver al suelo y cerrar","conteudo":"Cómo hacerlo: Ve al suelo: gato y vaca, rodillas que se balancean (Día 12) y torsión suave. Termina acostada, respirando.\nRespiración: La exhalación siempre más larga.\nRepeticiones: como se describió.\nVas a sentir: el cuerpo entero reunido, suelto y presente.\n⚠️ Señal para detenerte: respeta los límites del día; no todos los días son iguales."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Quédate acostada en silencio por un minuto al final. Siente todo lo que ya puedes lograr."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Fíjate: movimientos que en el Día 1 parecían raros ahora son familiares. Eso es el cuerpo reaprendiendo a moverse."}]}}},{"numero":4,"titulo":"Jueves","aula":{"titulo":"Recuperar (práctica ligera)","conteudo":{"intro":"Después de una secuencia intensa, un día de recuperación con las piernas apoyadas y respiración larga. Cuidar tu descanso también es practicar.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Acostada con las piernas apoyadas en una silla o pared (Día 11). Una cobija si quieres."},{"tipo":"passo","titulo":"Descanso activo","conteudo":"Cómo hacerlo: Con las piernas apoyadas, haz el barrido del cuerpo (Día 4), soltando región por región. Después solo respira.\nRespiración: Exhalación bien larga, como un suspiro.\nRepeticiones: 5 a 6 minutos.\nVas a sentir: todo el sistema desacelerando.\n⚠️ Señal para detenerte: sal de la posición si hormiguea demasiado."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Rueda hacia un lado, descansa y levántate sin apuro. Recuperada y lista para los últimos días."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"El progreso no ocurre solo en el esfuerzo — ocurre en el descanso, cuando el cuerpo asimila lo que aprendió."}]}}},{"numero":5,"titulo":"Viernes","aula":{"titulo":"Respiración y movimiento","conteudo":{"intro":"Hoy la protagonista es la respiración, guiando todo. Una práctica fluida en la que cada movimiento nace de un ciclo respiratorio.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"De pie, con espacio. Empieza solo observando la respiración durante 3 ciclos."},{"tipo":"passo","titulo":"Movimiento nacido del aire","conteudo":"Cómo hacerlo: Deja que cada inspiración \"abra\" un movimiento (subir los brazos, crecer, abrir el pecho) y cada exhalación \"suelte\" (bajar, redondear, girar). No cuentes movimientos — deja que la respiración elija.\nRespiración: La respiración comanda; el cuerpo obedece despacio.\nRepeticiones: 5 a 7 minutos de flujo libre.\nVas a sentir: el cuerpo moviéndose solo, guiado por el aire, sin \"decidir\".\n⚠️ Señal para detenerte: si la respiración se acelera o te falta el aire, detente y normalízala."},{"tipo":"passo","titulo":"Aquietarse","conteudo":"Cómo hacerlo: Poco a poco, deja que los movimientos se vuelvan más pequeños hasta detenerte de pie, quieta, solo respirando.\nRespiración: Respiración natural, larga.\nRepeticiones: 1 minuto.\nVas a sentir: la calma que queda después del movimiento consciente.\n⚠️ Señal para detenerte: ninguna — es el aterrizaje."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Abre los ojos despacio. Fíjate cómo el cuerpo y la respiración están del mismo lado ahora."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Esa conexión respiración-movimiento es el corazón de lo somático. Cuando sucede, el \"ejercicio\" desaparece y se vuelve presencia."}]}}},{"numero":6,"titulo":"Sábado","aula":{"titulo":"Mi práctica","conteudo":{"intro":"Hoy armas tu propia secuencia. Ya tienes el repertorio para esto — vamos a guiarte para elegir lo que tu cuerpo más pide.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Espacio libre. Piensa: ¿qué región tuya pide más cuidado hoy? ¿Cuello/hombros? ¿Zona lumbar/cadera? ¿O el cuerpo entero?"},{"tipo":"passo","titulo":"Elige un comienzo","conteudo":"Cómo hacerlo: Empieza con un movimiento de percepción y respiración (Día 1, 2 o 4). Date 2 a 3 minutos solo para llegar.\nRespiración: Respiración tranquila.\nRepeticiones: 2 a 3 minutos.\nVas a sentir: la diferencia entre \"empezar acelerada\" y \"empezar llegando\".\n⚠️ Señal para detenerte: sin saltarte la llegada; ella prepara el resto."},{"tipo":"passo","titulo":"Elige el centro","conteudo":"Cómo hacerlo: Elige 2 o 3 movimientos de las semanas 2 y 3 para la región que pidió atención. Haz cada uno con calma.\nRespiración: La respiración guiando.\nRepeticiones: 10 a 12 minutos.\nVas a sentir: el cuerpo respondiendo a lo que TÚ elegiste — eso es autonomía.\n⚠️ Señal para detenerte: si algún movimiento no te cae bien hoy, cámbialo por otro."},{"tipo":"passo","titulo":"Elige un cierre","conteudo":"Cómo hacerlo: Termina con algo restaurativo (piernas apoyadas, torsión suave o abrazo de rodillas) y respiración larga.\nRespiración: Exhalación larga.\nRepeticiones: 3 a 4 minutos.\nVas a sentir: el cierre que deja al cuerpo en paz.\n⚠️ Señal para detenerte: ninguna."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Acabas de conducir tu propia práctica. Ese es el objetivo de los 28 días: tú al mando de tu cuerpo."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"Guarda mentalmente (o anota) la secuencia que más bien te hizo hoy. Es el comienzo de tu práctica para toda la vida."}]}}},{"numero":7,"titulo":"Domingo","aula":{"titulo":"Siguiendo adelante","conteudo":{"intro":"¡Último día! Una secuencia completa de celebración y un mapa para que sigas después. El protocolo termina, la práctica se queda.","blocos":[{"tipo":"texto","titulo":"Preparación","conteudo":"Espacio libre, tapete y un apoyo. Empieza de pie, con una respiración de gratitud por el camino recorrido hasta aquí."},{"tipo":"passo","titulo":"La secuencia del recorrido","conteudo":"Cómo hacerlo: Encadena con calma: brazos que respiran → espiral → roll down/up → círculos de cadera → al suelo para gato y vaca → torsión suave → acostada para cerrar.\nRespiración: La respiración guiándolo todo, sin apuro.\nRepeticiones: un recorrido entero, saboreado.\nVas a sentir: el cuerpo que conociste a lo largo de 28 días, más suelto y presente.\n⚠️ Señal para detenerte: respeta el día; celebrar no es forzar."},{"tipo":"texto","titulo":"Cómo continuar después de los 28 días","conteudo":"No necesitas una fórmula: 10 a 20 minutos, de 3 a 5 veces por semana, ya sostienen todo lo que ganaste. En los días agitados, haz solo la llegada y la respiración — igual vale. Vuelve a cualquier clase cuando quieras; siguen aquí. Y, sobre todo: sigue escuchando a tu cuerpo. Te lo agradece todos los días."},{"tipo":"texto","titulo":"Para terminar","conteudo":"Recuéstate por un minuto al final y reconoce: apareciste 28 días por ti. Eso cambia la relación con tu propio cuerpo — y nadie te lo quita."},{"tipo":"dica","titulo":"Consejo del día","conteudo":"El resultado más grande no es físico: es saber que eres capaz de cuidarte, un movimiento a la vez. Felicidades. 🤍"}]}}}]}]$weeks$::jsonb;
  v_ex    jsonb := $exs$[{"dia":1,"ordem":1,"nome":"Respiración de tres tiempos","descricao":"Día 1 — Respirar y asentarse","instr":"Preparación: Acostada boca arriba, rodillas dobladas, pies apoyados en el suelo. Una mano sobre el vientre, otra sobre el pecho.\nMovimiento: Deja que el aire entre primero llenando el vientre, después las costillas, por último el pecho. Suelta en el orden inverso, sin prisa.\nRespiración: Inspira en 4 tiempos, suelta en 6. Sin retener el aire en ningún momento.\nQué vas a sentir: La mano del vientre subiendo antes que la mano del pecho. Es común que, al principio, pase lo contrario — está bien.\nAtención: Si sientes mareo, vuelve a respirar con normalidad por unos instantes."},{"dia":1,"ordem":2,"nome":"Balanceo de la pelvis","descricao":"Día 1 — Respirar y asentarse","instr":"Preparación: Acostada boca arriba, rodillas dobladas, pies apoyados al ancho de la cadera.\nMovimiento: Inclina la pelvis levemente hacia atrás, pegando la zona lumbar al suelo. Después vuelve despacio, dejando un pequeño espacio debajo de la lumbar. Movimiento pequeño, casi invisible desde afuera.\nRespiración: Suelta el aire al pegar la lumbar, inspira al volver.\nQué vas a sentir: La lumbar tocando y despegándose del suelo. El movimiento nace de la pelvis, no de las piernas.\nAtención: No fuerces la lumbar contra el suelo. Es un balanceo suave, no una presión."},{"dia":1,"ordem":3,"nome":"Rodillas que se abrazan","descricao":"Día 1 — Respirar y asentarse","instr":"Preparación: Acostada boca arriba. Lleva una rodilla a la vez hacia el pecho y envuélvela con las manos o los brazos.\nMovimiento: Tira de las rodillas suavemente hacia el pecho, sostén durante tres respiraciones y suelta un poco. Repite.\nRespiración: Suelta el aire al acercar las rodillas, inspira al aflojar.\nQué vas a sentir: Un estiramiento agradable en la lumbar y los glúteos.\nAtención: Si el cuello se tensiona, apoya la cabeza en un cojín bajo."},{"dia":1,"ordem":4,"nome":"Pies que empujan","descricao":"Día 1 — Respirar y asentarse","instr":"Preparación: Acostada boca arriba, rodillas dobladas, pies bien apoyados en el suelo.\nMovimiento: Presiona los pies contra el suelo como si quisieras empujarlo lejos, sin levantar la cadera. Sostén dos segundos y suelta por completo.\nRespiración: Suelta el aire al presionar, inspira al relajar.\nQué vas a sentir: Activación detrás de los muslos y en los glúteos, sin esfuerzo en la lumbar.\nAtención: La cadera permanece en el suelo. Si se levanta, reduce la fuerza."},{"dia":1,"ordem":5,"nome":"Descanso de la lumbar","descricao":"Día 1 — Respirar y asentarse","instr":"Preparación: Acostada boca arriba, pantorrillas apoyadas sobre el asiento de una silla o sofá, rodillas en ángulo recto.\nMovimiento: Ninguno. Solo permanece en la posición, dejando que el peso del cuerpo se hunda.\nRespiración: Libre y natural. Observa el aire entrando y saliendo.\nQué vas a sentir: La lumbar soltándose poco a poco. Es común sentir que el cuerpo “se hunde” después del primer minuto.\nAtención: Permanece de 2 a 3 minutos. Si sientes hormigueo en las piernas, bájalas y vuelve a empezar."},{"dia":2,"ordem":1,"nome":"Hombros que se derriten","descricao":"Día 2 — Soltar la parte alta del cuerpo","instr":"Preparación: Sentada en una silla, pies apoyados en el suelo, columna apoyada en el respaldo.\nMovimiento: Sube los hombros hacia las orejas lentamente, sostén durante tres segundos, y déjalos caer de una vez, como si soltaras un peso.\nRespiración: Inspira al subir, suelta el aire al dejarlos caer.\nQué vas a sentir: El contraste entre la tensión y la relajación. Es esa diferencia la que le enseña al cuerpo a soltar.\nAtención: La caída es pasiva, no empujes los hombros hacia abajo."},{"dia":2,"ordem":2,"nome":"Cabeza que rueda","descricao":"Día 2 — Soltar la parte alta del cuerpo","instr":"Preparación: Sentada, columna apoyada, hombros relajados.\nMovimiento: Lleva el mentón hacia el pecho y rueda la cabeza despacio hacia un lado, luego vuelve al centro y ve hacia el otro. Solo medio círculo, nunca hacia atrás.\nRespiración: Libre, sin retener.\nQué vas a sentir: Estiramiento en los laterales del cuello. Puede haber leves crujidos — es normal.\nAtención: Nunca lleves la cabeza hacia atrás. Si sientes mareo, detente y vuelve al centro."},{"dia":2,"ordem":3,"nome":"Brazos de ala","descricao":"Día 2 — Soltar la parte alta del cuerpo","instr":"Preparación: Sentada, brazos doblados a la altura del pecho, codos a la altura de los hombros.\nMovimiento: Abre los codos hacia los lados, acercando los omóplatos, y vuelve al frente. Movimiento horizontal y lento.\nRespiración: Inspira al abrir, suelta el aire al cerrar.\nQué vas a sentir: Los omóplatos acercándose en la espalda al abrir.\nAtención: Los hombros permanecen bajos. Si suben hacia las orejas, reduce la amplitud."},{"dia":2,"ordem":4,"nome":"Pecho que se abre","descricao":"Día 2 — Soltar la parte alta del cuerpo","instr":"Preparación: Sentada en el borde de la silla, manos apoyadas detrás de la cadera, dedos apuntando hacia atrás.\nMovimiento: Desliza las manos un poco más hacia atrás, abriendo el pecho, y sostén durante tres respiraciones. Vuelve y repite.\nRespiración: Inspira profundamente en la apertura, sintiendo el pecho expandirse.\nQué vas a sentir: Apertura en el frente del pecho y los hombros.\nAtención: Mantén el cuello largo. No eches la cabeza hacia atrás."},{"dia":2,"ordem":5,"nome":"Nuca larga","descricao":"Día 2 — Soltar la parte alta del cuerpo","instr":"Preparación: Sentada, columna apoyada, manos sobre los muslos.\nMovimiento: Lleva el mentón hacia el pecho despacio, estirando la nuca. Sostén y vuelve lentamente. Después inclina la cabeza hacia cada lado, oreja en dirección al hombro.\nRespiración: Suelta el aire al inclinar, inspira al volver al centro.\nQué vas a sentir: Estiramiento en la nuca y los laterales del cuello.\nAtención: No uses las manos para tirar de la cabeza. Deja que su propio peso haga el trabajo."},{"dia":3,"ordem":1,"nome":"Cadera que se balancea","descricao":"Día 3 — Abrir las caderas","instr":"Preparación: Acostada boca arriba, rodillas dobladas, pies apoyados.\nMovimiento: Desliza la cadera suavemente hacia un lado y hacia el otro, como un balanceo lento. Movimiento pequeño.\nRespiración: Libre, acompañando el ritmo del balanceo.\nQué vas a sentir: Soltura en la zona de la cadera y la lumbar.\nAtención: Los hombros permanecen apoyados. El movimiento es solo de la cadera hacia abajo."},{"dia":3,"ordem":2,"nome":"Rodilla que se abre","descricao":"Día 3 — Abrir las caderas","instr":"Preparación: Acostada boca arriba, rodillas dobladas, pies apoyados.\nMovimiento: Deja que una rodilla se abra hacia el lado, en dirección al suelo, manteniendo el pie apoyado. Ve hasta donde te sea cómodo y vuelve. Alterna los lados.\nRespiración: Suelta el aire al abrir, inspira al volver.\nQué vas a sentir: Apertura en la ingle y la parte interna del muslo.\nAtención: La cadera del lado opuesto permanece apoyada. No fuerces la rodilla hasta el suelo."},{"dia":3,"ordem":3,"nome":"Mariposa acostada","descricao":"Día 3 — Abrir las caderas","instr":"Preparación: Acostada boca arriba, plantas de los pies unidas, rodillas abiertas hacia los lados.\nMovimiento: Permanece en la posición dejando que el peso de las piernas abra las rodillas naturalmente. Si prefieres, apoya cojines debajo de las rodillas.\nRespiración: Libre y profunda. En cada espiración, imagina que las caderas se sueltan un poco más.\nQué vas a sentir: Estiramiento en la parte interna de los muslos.\nAtención: Nunca empujes las rodillas hacia abajo con las manos. Permanece de 1 a 2 minutos."},{"dia":3,"ordem":4,"nome":"Pierna que desliza","descricao":"Día 3 — Abrir las caderas","instr":"Preparación: Acostada boca arriba, rodillas dobladas, pies apoyados.\nMovimiento: Desliza un talón por el suelo, extendiendo la pierna hasta donde logres mantener la lumbar tranquila. Vuelve deslizando. Alterna.\nRespiración: Suelta el aire al extender, inspira al recoger.\nQué vas a sentir: El trabajo suave en el frente del muslo y en el centro del cuerpo al controlar el movimiento.\nAtención: Si la lumbar se arquea demasiado, extiende menos la pierna."},{"dia":3,"ordem":5,"nome":"Figura cuatro","descricao":"Día 3 — Abrir las caderas","instr":"Preparación: Acostada boca arriba, rodillas dobladas. Cruza el tobillo derecho sobre el muslo izquierdo, formando un “cuatro”.\nMovimiento: Permanece en la posición. Si quieres más intensidad, acerca el muslo de apoyo al pecho con las manos.\nRespiración: Libre. Tres a cinco respiraciones de cada lado.\nQué vas a sentir: Estiramiento en el glúteo de la pierna cruzada.\nAtención: Si sientes incomodidad en la rodilla, reduce o sal de la posición."},{"dia":4,"ordem":1,"nome":"Gato y vaca en el suelo","descricao":"Día 4 — Columna viva","instr":"Preparación: En cuatro apoyos, manos bajo los hombros, rodillas bajo la cadera. Si las rodillas molestan, usa una toalla doblada.\nMovimiento: Redondea la espalda llevando la mirada al ombligo, después invierte, dejando que la barriga baje y la mirada suba levemente. Alterna lentamente.\nRespiración: Suelta el aire al redondear, inspira al abrir.\nQué vas a sentir: La columna moviéndose por completo, vértebra por vértebra.\nAtención: Amplitud cómoda. Si la muñeca molesta, apoya los antebrazos."},{"dia":4,"ordem":2,"nome":"Columna que se desenrolla","descricao":"Día 4 — Columna viva","instr":"Preparación: Sentada en el borde de la silla, pies apoyados, manos sobre los muslos.\nMovimiento: Enrolla la columna hacia adelante despacio, empezando por la cabeza, dejando que las manos se deslicen por los muslos. Vuelve desenrollando de abajo hacia arriba.\nRespiración: Suelta el aire al bajar, inspira al subir.\nQué vas a sentir: Cada parte de la columna doblándose y volviendo en secuencia.\nAtención: Baja solo hasta donde te sea cómodo. No necesitas llegar a los pies."},{"dia":4,"ordem":3,"nome":"Torsión del reloj","descricao":"Día 4 — Columna viva","instr":"Preparación: Acostada boca arriba, rodillas dobladas y juntas, brazos abiertos en cruz.\nMovimiento: Deja que las rodillas caigan despacio hacia un lado, manteniendo los hombros apoyados. Vuelve al centro y ve hacia el otro lado.\nRespiración: Suelta el aire al girar, inspira al volver.\nQué vas a sentir: Rotación suave en la columna y estiramiento en el lateral del tronco.\nAtención: Si un hombro se levanta del suelo, reduce la amplitud de la torsión."},{"dia":4,"ordem":4,"nome":"Ondulación de la columna","descricao":"Día 4 — Columna viva","instr":"Preparación: En cuatro apoyos, manos bajo los hombros.\nMovimiento: Haz un movimiento continuo y ondulatorio, como una ola que recorre la columna desde el cóccix hasta la cabeza, y vuelve.\nRespiración: Libre, acompañando el ritmo de la ola.\nQué vas a sentir: El movimiento pasando por zonas de la columna que suelen quedar quietas.\nAtención: Es un movimiento fluido, sin pausas. Si te confundes, vuelve al gato y vaca."},{"dia":4,"ordem":5,"nome":"Estiramiento en C","descricao":"Día 4 — Columna viva","instr":"Preparación: Sentada, una mano apoyada en el asiento junto a la cadera.\nMovimiento: Lleva el otro brazo por encima de la cabeza, inclinando el tronco hacia el lado y formando un arco. Sostén y vuelve. Alterna.\nRespiración: Inspira al subir el brazo, suelta el aire en la inclinación.\nQué vas a sentir: Estiramiento en todo el lateral del tronco, desde las costillas hasta la cadera.\nAtención: Mantén los dos glúteos apoyados en el asiento."},{"dia":5,"ordem":1,"nome":"Barriga que respira","descricao":"Día 5 — Centro sin esfuerzo","instr":"Preparación: Acostada boca arriba, rodillas dobladas, manos sobre la barriga.\nMovimiento: Al soltar el aire, lleva el ombligo suavemente hacia la columna, como si cerraras un cinturón por dentro. Suelta al inspirar.\nRespiración: La activación ocurre en la espiración. Nunca retengas el aire.\nQué vas a sentir: Una activación profunda y sutil en el fondo de la barriga — no es contraer con fuerza.\nAtención: Si la barriga se endurece por fuera o el aire se queda atrapado, estás forzando demasiado."},{"dia":5,"ordem":2,"nome":"Pierna que cae y vuelve","descricao":"Día 5 — Centro sin esfuerzo","instr":"Preparación: Acostada boca arriba, rodillas dobladas, pies apoyados, manos al lado del cuerpo.\nMovimiento: Activa suavemente la barriga y deja que una rodilla se abra hacia el lado, manteniendo la cadera estable. Vuelve con control. Alterna.\nRespiración: Suelta el aire al abrir, inspira al volver.\nQué vas a sentir: El centro del cuerpo trabajando para impedir que la cadera gire junto.\nAtención: Si la cadera opuesta se levanta, reduce la amplitud."},{"dia":5,"ordem":3,"nome":"Cabeza que se levanta despacio","descricao":"Día 5 — Centro sin esfuerzo","instr":"Preparación: Acostada boca arriba, rodillas dobladas, manos detrás de la cabeza solo como apoyo.\nMovimiento: Suelta el aire, lleva el mentón levemente hacia el pecho y eleva la cabeza pocos centímetros. Vuelve despacio.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: Activación en la barriga, no en el cuello.\nAtención: Las manos apoyan, no tiran. Si el cuello duele, detente."},{"dia":5,"ordem":4,"nome":"Puente suave","descricao":"Día 5 — Centro sin esfuerzo","instr":"Preparación: Acostada boca arriba, rodillas dobladas, pies apoyados al ancho de la cadera.\nMovimiento: Eleva la cadera unos centímetros del suelo y baja despacio, apoyando vértebra por vértebra.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: Activación en los glúteos y detrás de los muslos.\nAtención: No subas más allá de lo cómodo. Si la lumbar se queja, eleva menos."},{"dia":5,"ordem":5,"nome":"Plancha apoyada","descricao":"Día 5 — Centro sin esfuerzo","instr":"Preparación: De pie, frente a una pared, manos apoyadas a la altura de los hombros, pies a un paso de distancia.\nMovimiento: Mantén el cuerpo en línea recta desde la cabeza hasta los pies, barriga levemente activa. Sostén de 15 a 20 segundos.\nRespiración: Continua y tranquila. No retengas el aire.\nQué vas a sentir: Activación suave en todo el centro del cuerpo.\nAtención: Si la lumbar se hunde, acerca los pies a la pared."},{"dia":6,"ordem":1,"nome":"Sentadilla en la silla","descricao":"Día 6 — Piernas y apoyo","instr":"Preparación: De pie, de espaldas a una silla, pies al ancho de la cadera.\nMovimiento: Baja sentándote en la silla con control, apoyando las manos en las rodillas si lo necesitas. Levántate usando la fuerza de las piernas.\nRespiración: Inspira al bajar, suelta el aire al subir.\nQué vas a sentir: Trabajo en el frente de los muslos y en los glúteos.\nAtención: Las rodillas apuntan en la misma dirección que los pies. Baja despacio, sin dejarte caer."},{"dia":6,"ordem":2,"nome":"Pantorrilla que sube","descricao":"Día 6 — Piernas y apoyo","instr":"Preparación: De pie, manos apoyadas en el respaldo de una silla o en la pared.\nMovimiento: Sube los talones, quedando en la punta de los pies, sostén un segundo y baja despacio.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: Trabajo en las pantorrillas y activación en los pies.\nAtención: La bajada es lenta — es ahí donde está el trabajo."},{"dia":6,"ordem":3,"nome":"Pierna que se abre de pie","descricao":"Día 6 — Piernas y apoyo","instr":"Preparación: De pie, una mano apoyada en la pared o silla.\nMovimiento: Abre una pierna hacia el lado hasta donde logres mantener el tronco recto, y vuelve con control. Alterna.\nRespiración: Suelta el aire al abrir, inspira al volver.\nQué vas a sentir: Trabajo en el lateral de la cadera.\nAtención: El tronco permanece erguido. No te inclines hacia el lado opuesto."},{"dia":6,"ordem":4,"nome":"Paso que retrasa","descricao":"Día 6 — Piernas y apoyo","instr":"Preparación: De pie, mano apoyada en una silla, pies al ancho de la cadera.\nMovimiento: Da un paso hacia atrás con una pierna, transfiriendo poco peso, y vuelve al centro. Alterna.\nRespiración: Inspira al dar el paso, suelta el aire al volver.\nQué vas a sentir: Equilibrio y trabajo en la pierna de apoyo.\nAtención: Paso corto al principio. Aumenta conforme ganes seguridad."},{"dia":6,"ordem":5,"nome":"Equilibrio en un pie","descricao":"Día 6 — Piernas y apoyo","instr":"Preparación: De pie, junto a una pared o silla, con la mano apoyada levemente como seguridad.\nMovimiento: Eleva un pie pocos centímetros del suelo y mantén el equilibrio de 10 a 20 segundos. Alterna.\nRespiración: Tranquila y continua.\nQué vas a sentir: Los pequeños ajustes constantes del pie y del tobillo — así es como se entrena el equilibrio.\nAtención: Mantén siempre el apoyo al alcance de la mano."},{"dia":7,"ordem":1,"nome":"Desperezo completo","descricao":"Día 7 — Cuerpo entero, despacio","instr":"Preparación: Acostada boca arriba, piernas extendidas, brazos por encima de la cabeza.\nMovimiento: Estira todo el cuerpo como al despertar: brazos hacia arriba, pies hacia abajo, estirando al máximo. Sostén y suelta de una vez.\nRespiración: Inspira al estirar, suelta el aire al relajar.\nQué vas a sentir: Todo el cuerpo estirándose de punta a punta, y la relajación profunda después.\nAtención: Este es el movimiento más natural que existe. Deja que el cuerpo te guíe."},{"dia":7,"ordem":2,"nome":"Rodar hacia el lado","descricao":"Día 7 — Cuerpo entero, despacio","instr":"Preparación: Acostada boca arriba, brazos al lado del cuerpo.\nMovimiento: Rueda todo el cuerpo hacia un lado con control, como un solo bloque, y vuelve. Alterna.\nRespiración: Libre, acompañando el movimiento.\nQué vas a sentir: La coordinación entre tronco, cadera y piernas.\nAtención: Movimiento lento. La intención es sentir la secuencia, no la velocidad."},{"dia":7,"ordem":3,"nome":"Secuencia para levantarse","descricao":"Día 7 — Cuerpo entero, despacio","instr":"Preparación: Acostada boca arriba.\nMovimiento: Rueda hacia el lado, apoya la mano en el suelo, siéntate, apóyate para quedar de rodillas y ponte de pie. Después haz el camino inverso para volver al suelo.\nRespiración: Libre, sin retener en ninguna transición.\nQué vas a sentir: Cómo el cuerpo se organiza para salir del suelo — un gesto que usamos toda la vida sin darnos cuenta.\nAtención: Usa apoyo siempre que lo necesites. Ve despacio."},{"dia":7,"ordem":4,"nome":"Balanceo de pie","descricao":"Día 7 — Cuerpo entero, despacio","instr":"Preparación: De pie, pies al ancho de la cadera, brazos sueltos.\nMovimiento: Balancea el cuerpo suavemente hacia adelante y hacia atrás, después hacia los lados, encontrando el punto de equilibrio en el centro.\nRespiración: Libre y tranquila.\nQué vas a sentir: Los pies trabajando todo el tiempo para mantenerte de pie.\nAtención: Movimiento pequeño. Si sientes inestabilidad, quédate cerca de una pared."},{"dia":7,"ordem":5,"nome":"Silencio del cuerpo","descricao":"Día 7 — Cuerpo entero, despacio","instr":"Preparación: Acostada boca arriba, piernas extendidas o rodillas dobladas, lo que te resulte más cómodo.\nMovimiento: Ninguno. Solo permanece, recorriendo el cuerpo con la atención, de los pies a la cabeza.\nRespiración: Natural. Sin controlar.\nQué vas a sentir: Cómo está el cuerpo ahora, después de toda la semana de práctica.\nAtención: Permanece de 2 a 3 minutos. Este es el cierre — no te lo saltes."}]$exs$::jsonb;
  v_st    jsonb := $sts$[{"ordem":1,"nome":"Respirar y llegar","descricao":"Acostada boca arriba, rodillas dobladas. Solo respira durante tres minutos, observando el aire entrar y salir. Sin mover nada. Es el primer contacto con el cuerpo."},{"ordem":2,"nome":"Estirar de punta a punta","descricao":"Acostada, brazos por encima de la cabeza. Estira todo el cuerpo durante unos segundos y suelta. Repite tres veces."},{"ordem":3,"nome":"Rodillas al pecho","descricao":"Acostada, lleva las rodillas al pecho y envuélvelas con los brazos. Sostén durante cinco respiraciones, sintiendo la lumbar apoyada en el suelo."},{"ordem":4,"nome":"Torsión acostada","descricao":"Acostada, rodillas dobladas y juntas, brazos abiertos. Deja que las rodillas caigan hacia un lado y la mirada hacia el otro. Cinco respiraciones de cada lado."},{"ordem":5,"nome":"Cuello en tres direcciones","descricao":"Sentada. Inclina la cabeza hacia la derecha, hacia la izquierda y hacia adelante, sosteniendo tres respiraciones en cada posición. Nunca hacia atrás."},{"ordem":6,"nome":"Hombros en círculo","descricao":"Sentada. Haz círculos lentos con los hombros, cinco veces hacia atrás y cinco hacia adelante."},{"ordem":7,"nome":"Abrir los brazos","descricao":"Sentada en el borde de la silla, manos apoyadas atrás. Abre el pecho y sostén durante cinco respiraciones."},{"ordem":8,"nome":"Estirar detrás de la pierna","descricao":"Sentada, una pierna extendida al frente con el talón en el suelo. Inclina el tronco levemente hasta sentir la parte de atrás de la pierna. Cinco respiraciones de cada lado."},{"ordem":9,"nome":"Cadera en cuatro","descricao":"Acostada, tobillo cruzado sobre el muslo opuesto. Sostén durante cinco respiraciones de cada lado."},{"ordem":10,"nome":"Reposo final","descricao":"Acostada, piernas y brazos sueltos. Dos minutos de inmovilidad, solo percibiendo el cuerpo."}]$sts$::jsonb;
  v_diet  jsonb := $diet$[{"numero":1,"refeicoes":{"cafe":{"titulo":"Desayuno","itens":["Café con leche","Pan integral con huevo revuelto","Papaya"]},"almoco":{"titulo":"Almuerzo","itens":["Arroz","Frijoles","Pollo a la plancha","Ensalada de hojas verdes"]},"lanche":{"titulo":"Merienda","itens":["Yogur natural","Banana"]},"jantar":{"titulo":"Cena","itens":["Sopa de verduras","Tostada integral"]}}},{"numero":2,"refeicoes":{"cafe":{"titulo":"Desayuno","itens":["Tapioca con queso","Jugo de naranja natural"]},"almoco":{"titulo":"Almuerzo","itens":["Arroz integral","Lentejas","Carne molida salteada","Calabacín"]},"lanche":{"titulo":"Merienda","itens":["Fruta de estación","Nueces"]},"jantar":{"titulo":"Cena","itens":["Omelette de verduras","Ensalada verde"]}}},{"numero":3,"refeicoes":{"cafe":{"titulo":"Desayuno","itens":["Batido de banana con avena"]},"almoco":{"titulo":"Almuerzo","itens":["Arroz","Frijoles","Pescado al horno","Zanahoria y remolacha"]},"lanche":{"titulo":"Merienda","itens":["Yogur","Manzana"]},"jantar":{"titulo":"Cena","itens":["Wrap integral con pollo y ensalada"]}}},{"numero":4,"refeicoes":{"cafe":{"titulo":"Desayuno","itens":["Café con leche","Pan integral con queso crema","Mandarina"]},"almoco":{"titulo":"Almuerzo","itens":["Puré de papa","Pollo deshebrado","Brócoli"]},"lanche":{"titulo":"Merienda","itens":["Mix de frutas"]},"jantar":{"titulo":"Cena","itens":["Sopa de calabaza con pollo"]}}},{"numero":5,"refeicoes":{"cafe":{"titulo":"Desayuno","itens":["Huevos revueltos","Rebanada de melón"]},"almoco":{"titulo":"Almuerzo","itens":["Arroz","Frijoles","Bistec a la plancha","Ensalada de tomate"]},"lanche":{"titulo":"Merienda","itens":["Yogur con granola"]},"jantar":{"titulo":"Cena","itens":["Panqueque de avena con queso fresco"]}}},{"numero":6,"refeicoes":{"cafe":{"titulo":"Desayuno","itens":["Tapioca con huevo"]},"almoco":{"titulo":"Almuerzo","itens":["Pasta integral","Salsa de tomate casera","Pollo","Ensalada"]},"lanche":{"titulo":"Merienda","itens":["Fruta","Puñado de nueces"]},"jantar":{"titulo":"Cena","itens":["Caldo de verduras","Tostada"]}}},{"numero":7,"refeicoes":{"cafe":{"titulo":"Desayuno","itens":["Café con leche","Bizcocho casero de maíz (rebanada pequeña)","Fruta"]},"almoco":{"titulo":"Almuerzo","itens":["Guiso ligero de frijoles con verduras","Arroz","Naranja"]},"lanche":{"titulo":"Merienda","itens":["Yogur natural"]},"jantar":{"titulo":"Cena","itens":["Ensalada completa con atún y huevo"]}}}]$diet$::jsonb;
  v_week jsonb; v_dia jsonb; v_e jsonb; v_s jsonb; v_d jsonb;
begin
  -- Programa canônico (o que tem as aulas).
  select p.id into v_program_id
    from public.programs p
    join public.products pr on pr.id = p.product_id
   where pr.slug in ('drenagem-tailandesa', 'ritual-do-tapetinho', 'pilates-somatico', 'caminhada-japonesa')
   order by p.ativo desc
   limit 1;

  -- 1) Semanas / dias / aulas (por posição).
  if v_program_id is not null then
    for v_week in select * from jsonb_array_elements(v_weeks)
    loop
      update public.program_weeks
         set titulo = v_week->>'titulo'
       where program_id = v_program_id and numero = (v_week->>'numero')::int;

      for v_dia in select * from jsonb_array_elements(v_week->'dias')
      loop
        update public.program_days d
           set titulo = v_dia->>'titulo'
          from public.program_weeks w
         where d.week_id = w.id and w.program_id = v_program_id
           and w.numero = (v_week->>'numero')::int and d.numero = (v_dia->>'numero')::int;

        update public.lessons l
           set titulo = v_dia->'aula'->>'titulo',
               conteudo = v_dia->'aula'->'conteudo'
          from public.program_days d
          join public.program_weeks w on w.id = d.week_id
         where l.day_id = d.id and w.program_id = v_program_id
           and w.numero = (v_week->>'numero')::int and d.numero = (v_dia->>'numero')::int;
      end loop;
    end loop;
  end if;

  -- 2) Exercícios + variação v1 (por dia_do_ciclo / ordem_no_dia).
  for v_e in select * from jsonb_array_elements(v_ex)
  loop
    update public.exercises
       set nome = v_e->>'nome', descricao = v_e->>'descricao'
     where dia_do_ciclo = (v_e->>'dia')::int and ordem_no_dia = (v_e->>'ordem')::int
    returning id into v_ex_id;

    if v_ex_id is not null then
      update public.exercise_variations
         set instrucoes = v_e->>'instr'
       where exercise_id = v_ex_id and nivel = 1;
    end if;
  end loop;

  -- 3) Alongamentos (por ordem).
  for v_s in select * from jsonb_array_elements(v_st)
  loop
    update public.stretches
       set nome = v_s->>'nome', descricao = v_s->>'descricao'
     where ordem = (v_s->>'ordem')::int;
  end loop;

  -- 4) Cardápio base (por numero) — plano incluso (product_id null).
  for v_d in select * from jsonb_array_elements(v_diet)
  loop
    update public.diet_days dd
       set refeicoes = v_d->'refeicoes'
      from public.diet_plans dp
     where dd.diet_plan_id = dp.id and dp.product_id is null
       and dd.numero = (v_d->>'numero')::int;
  end loop;
end
$migration$;

-- 5) Produtos (nome/descrição/sales_page em espanhol).
update public.products
   set nome = $pn$Protocolo 28 Dias: Drenagem Tailandesa$pn$,
       descricao = $pd$Movimentos suaves inspirados na massagem tailandesa: 28 dias de prática lenta e consciente para relaxar o corpo e soltar a tensão do dia, no seu ritmo e sem equipamento.$pd$,
       sales_page = $sp${"headline":"Reserve 28 dias para cuidar do seu corpo, no seu ritmo","subheadline":"Movimentos suaves inspirados na massagem tailandesa — sem academia, sem equipamento, sem pressa.","bullets":["Práticas guiadas de 10 a 25 minutos, dia a dia","Movimentos lentos e conscientes inspirados na massagem tailandesa","Feito para quem está começando — respeitando os seus limites"],"cta_label":"QUERO O PROTOCOLO"}$sp$::jsonb
 where slug = 'drenagem-tailandesa';

update public.products
   set descricao = 'Movimientos suaves de Pilates para practicar en casa, a tu ritmo y sin equipo.'
 where slug = 'pilates-hormonal';

update public.products
   set nome = 'Pilates en Silla',
       descricao = 'Ejercicios de bajo impacto usando solo una silla, para hacer en casa.'
 where slug = 'pilates-de-cadeira';

update public.products
   set nome = 'Menú Low Carb',
       descricao = 'Sugerencias de menú con menos carbohidratos, prácticas y caseras.'
 where slug = 'cardapio-low-carb';

notify pgrst, 'reload schema';

-- ---------------------------------------------------------------------
-- VERIFICAÇÃO
-- ---------------------------------------------------------------------
select 'exercicios traduzidos' as check, count(*)::text as valor from public.exercises where descricao is not null
union all select 'alongamentos', count(*)::text from public.stretches
union all select 'aulas', count(*)::text from public.lessons;
